export function extractStructured(value) {
  if (!value || typeof value !== "object") return null;
  if (Array.isArray(value.components) && Array.isArray(value.edges)) {
    return {
      summary:
        typeof value.summary === "string"
          ? value.summary
          : "Processed the current ink batch.",
      components: value.components,
      edges: value.edges,
      initialState: toStateRecord(value.initialState),
      generatedCode:
        typeof value.generatedCode === "string" ? value.generatedCode : "",
      tests: Array.isArray(value.tests) ? value.tests : [],
    };
  }
  for (const key of ["structured_output", "structuredOutput", "output"]) {
    const nested = extractStructured(value[key]);
    if (nested) return nested;
  }
  if (typeof value.result === "string") {
    return parseAgentJson(value.result);
  }
  return null;
}

export function parseAgentJson(text) {
  const trimmed = String(text || "").trim();
  const candidates = [trimmed];

  const fenced = trimmed.match(/```(?:json)?\s*([\s\S]*?)```/i);
  if (fenced) candidates.push(fenced[1].trim());

  const firstBrace = trimmed.indexOf("{");
  const lastBrace = trimmed.lastIndexOf("}");
  if (firstBrace >= 0 && lastBrace > firstBrace) {
    candidates.push(trimmed.slice(firstBrace, lastBrace + 1));
  }

  candidates.push(...balancedObjects(trimmed));

  for (const candidate of candidates) {
    try {
      const structured = extractStructured(JSON.parse(candidate));
      if (structured) return structured;
    } catch {
      // Try the next extraction.
    }
  }
  throw new Error("The agent did not return a valid app-graph response.");
}

