import assert from "node:assert/strict";
import test from "node:test";

// Node strips the TypeScript types natively; app-graph.ts is erasable TS.
const { restoreGraph } = await import("../app/lib/app-graph.ts");

function component(id, type = "Button", overrides = {}) {
  return { … };
}

function edge(id, source, target = "", overrides = {}) {
  return { … };
}

function graph(components = [], bindings = [], overrides = {}) {
  return { … };
}

test("round-trips a clean exported graph", () => {
  const restored = restoreGraph(
    graph([component("a"), component("b")], [edge("e1", "a", "b")], {
      initialState: { display: "0" },
    }),
  );

  assert.deepEqual(
    restored.components.map((entry) => entry.id),
    ["a", "b"],
  );
  assert.equal(restored.bindings.length, 1);
  assert.equal(restored.bindings[0].source, "a");
  assert.equal(restored.bindings[0].target, "b");
  assert.deepEqual(restored.initialState, { display: "0" });
  // events and actions are rebuilt from the surviving bindings, the same way
  // processing builds them.
  assert.deepEqual(restored.events, [
    { id: "event-e1", component: "a", event: "click" },
  ]);
  assert.deepEqual(restored.actions, [
    { id: "action-e1", type: "setState", target: "b" },
  ]);
});

test("rejects input that is not an object", () => { … });

test("falls back to Card for unknown component types", () => { … });

test("drops bindings whose references dangle", () => { … });

test("renames duplicate component ids", () => { … });

test("generates an id for a binding that has none", () => { … });

test("keeps only usable initialState values", () => { … });

test("falls back to local for unknown compiledBy and keeps omp", () => { … });

test("tolerates missing optional sections", () => { … });

