</head>
<body>
<canvas id="c" width="1024" height="768"></canvas>
<script>
const c = document.getElementById("c");
const ctx = c.getContext("2d");

// paper background
ctx.fillStyle = "#f7f4ec";
ctx.fillRect(0, 0, 1024, 768);

// hand-drawn-ish stroke helper: slight jitter on a rectangle
function sketchRect(x, y, w, h, color = "#111", width = 3) {
  ctx.strokeStyle = color;
  ctx.lineWidth = width;
  ctx.lineJoin = "round";
  const j = () => (Math.random() - 0.5) * 3;
  ctx.beginPath();
  ctx.moveTo(x + j(), y + j());
  ctx.lineTo(x + w + j(), y + j());
  ctx.lineTo(x + w + j(), y + h + j());
  ctx.lineTo(x + j(), y + h + j());
  ctx.closePath();
  ctx.stroke();
}

function sketchLine(x1, y1, x2, y2, color = "#111", width = 3) {
  ctx.strokeStyle = color;
  ctx.lineWidth = width;
  ctx.lineCap = "round";
  ctx.beginPath();
  ctx.moveTo(x1, y1);
  const mx = (x1 + x2) / 2 + (Math.random() - 0.5) * 8;
  const my = (y1 + y2) / 2 + (Math.random() - 0.5) * 8;
  ctx.quadraticCurveTo(mx, my, x2, y2);
  ctx.stroke();
}

function ink(text, x, y, size = 26, color = "#111") {
  ctx.fillStyle = color;
  ctx.font = `italic ${size}px "Comic Sans MS", "Segoe Script", cursive`;
  ctx.fillText(text, x, y);
}

// display: wide box at top
sketchRect(300, 80, 420, 90);
ink("0", 490, 140, 44);

// keypad: 4 columns x 3 rows of small boxes
const keys = [
  ["7", "8", "9", "+"],
  ["4", "5", "6", "-"],
  ["1", "2", "3", "*"],
  ["C", "0", "=", "/"],
];
const kx = 320, ky = 240, kw = 90, kh = 70, gap = 16;
for (let r = 0; r < 4; r++) {
  for (let col = 0; col < 4; col++) {
    const x = kx + col * (kw + gap);
    const y = ky + r * (kh + gap);
    sketchRect(x, y, kw, kh);
    ink(keys[r][col], x + kw / 2 - 8, y + kh / 2 + 10, 30);
  }
}

// handwritten note
ink("digits append to the display", 320, 640, 24);
ink("C clears everything", 320, 680, 24);

// arrow from the "7" key up to the display
sketchLine(365, 240, 365, 175);
// arrowhead
ctx.fillStyle = "#111";
ctx.beginPath();
ctx.moveTo(365, 170);
ctx.lineTo(357, 186);
ctx.lineTo(373, 186);
ctx.closePath();
ctx.fill();

document.title = "ready";
</script>
</body>
</html>
