/**
 * Strict structured-output schemas cannot express an open-ended map, so
 * initialState travels as key/value pairs and is folded back into an object
 * here. Tolerates a plain object too, in case a model returns one anyway.
 */
export function toStateRecord(value) {
  const record = {};
  if (Array.isArray(value)) {
    for (const entry of value) {
      if (entry && typeof entry.key === "string" && entry.key) {
        record[entry.key] = entry.value ?? "";
      }
    }
  } else if (value && typeof value === "object") {
    for (const [key, entry] of Object.entries(value)) {
      if (["string", "number", "boolean"].includes(typeof entry)) {
        record[key] = entry;
      }
    }
  }
  return record;
}

