/**
 * Parsing for whatever an agent CLI actually prints.
 *
 * Codex and Claude are schema-enforced and hand back clean JSON. Copilot has no
 * schema flag, so it writes the JSON itself — and writes it in ways that break
 * naive extraction: prose around it, fenced blocks, or several documents
 * concatenated with no separator. Everything here exists because one of those
 * happened.
 */

/**
 * Strict structured-output schemas cannot express an open-ended map, so
 * initialState travels as key/value pairs and is folded back into an object
 * here. Tolerates a plain object too, in case a model returns one anyway.
 */
export function toStateRecord(value) {
  const record = {};
  if (Array.isArray(value)) {
    for (const entry of value) {
      if (entry && typeof entry.key === "string" && entry.key) {
        record[entry.key] = entry.value ?? "";
      }
    }
  } else if (value && typeof value === "object") {
    for (const [key, entry] of Object.entries(value)) {
      if (["string", "number", "boolean"].includes(typeof entry)) {
        record[key] = entry;
      }
    }
  }
  return record;
}

/**
 * Returns each balanced top-level {...} in a string, ignoring braces inside
 * string literals. Slicing first-brace-to-last-brace welds concatenated
 * documents into something unparseable; this separates them.
 */
export function balancedObjects(text) {
  const found = [];
  let depth = 0;
  let start = -1;
  let inString = false;
  let escaped = false;

  for (let i = 0; i < text.length; i++) {
    const char = text[i];
    if (inString) {
      if (escaped) escaped = false;
      else if (char === "\\") escaped = true;
      else if (char === '"') inString = false;
      continue;
    }
    if (char === '"') {
      inString = true;
    } else if (char === "{") {
      if (depth === 0) start = i;
      depth++;
    } else if (char === "}") {
      depth--;
      if (depth === 0 && start >= 0) {
        found.push(text.slice(start, i + 1));
        start = -1;
      }
    }
  }
  return found;
}

export function extractStructured(value) {
  if (!value || typeof value !== "object") return null;
  if (Array.isArray(value.components) && Array.isArray(value.edges)) {
    return {
      summary:
        typeof value.summary === "string"
          ? value.summary
          : "Processed the current ink batch.",
      components: value.components,
      edges: value.edges,
      initialState: toStateRecord(value.initialState),
      generatedCode:
        typeof value.generatedCode === "string" ? value.generatedCode : "",
      tests: Array.isArray(value.tests) ? value.tests : [],
    };
  }
  for (const key of ["structured_output", "structuredOutput", "output"]) {
    const nested = extractStructured(value[key]);
    if (nested) return nested;
  }
  if (typeof value.result === "string") {
    return parseAgentJson(value.result);
  }
  return null;
}

export function parseAgentJson(text) {
  const trimmed = String(text || "").trim();
  const candidates = [trimmed];

  const fenced = trimmed.match(/```(?:json)?\s*([\s\S]*?)```/i);
  if (fenced) candidates.push(fenced[1].trim());

  const firstBrace = trimmed.indexOf("{");
  const lastBrace = trimmed.lastIndexOf("}");
  if (firstBrace >= 0 && lastBrace > firstBrace) {
    candidates.push(trimmed.slice(firstBrace, lastBrace + 1));
  }

  candidates.push(...balancedObjects(trimmed));

  for (const candidate of candidates) {
    try {
      const structured = extractStructured(JSON.parse(candidate));
      if (structured) return structured;
    } catch {
      // Try the next extraction.
    }
  }
  throw new Error("The agent did not return a valid app-graph response.");
}

