import assert from "node:assert/strict";
import test from "node:test";

import {
  balancedObjects,
  parseAgentJson,
  toStateRecord,
} from "../server/agent-response.mjs";

const MINIMAL = {
  summary: "ok",
  components: [],
  edges: [],
  initialState: [],
  generatedCode: "",
  tests: [],
};

test("accepts a clean structured response", () => {
  const parsed = parseAgentJson(JSON.stringify(MINIMAL));
  assert.equal(parsed.summary, "ok");
  assert.deepEqual(parsed.components, []);
});

test("digs the payload out of a fenced code block", () => {
  const text = `Here you go:\n\n\`\`\`json\n${JSON.stringify(MINIMAL)}\n\`\`\`\n\nHope that helps.`;
  assert.equal(parseAgentJson(text).summary, "ok");
});

test("unwraps the claude --output-format json envelope", () => {
  const envelope = JSON.stringify({
    type: "result",
    subtype: "success",
    structured_output: MINIMAL,
  });
  assert.equal(parseAgentJson(envelope).summary, "ok");
});

test("unwraps a stringified result field", () => {
  const envelope = JSON.stringify({ result: JSON.stringify(MINIMAL) });
  assert.equal(parseAgentJson(envelope).summary, "ok");
});

// Copilot has no schema flag and streamed its answer twice, back to back.
// first-brace-to-last-brace welds them into invalid JSON.
test("takes the first of several concatenated documents", () => {
  const first = { ...MINIMAL, summary: "first" };
  const second = { ...MINIMAL, summary: "second" };
  const text = JSON.stringify(first) + JSON.stringify(second);
  assert.throws(() => JSON.parse(text), "fixture should be invalid on its own");
  assert.equal(parseAgentJson(text).summary, "first");
});

test("survives prose wrapped around the payload", () => {
  const text = `I looked at the sketch.\n${JSON.stringify(MINIMAL)}\nLet me know!`;
  assert.equal(parseAgentJson(text).summary, "ok");
});

test("balancedObjects ignores braces inside string literals", () => {
  const text = '{"handler":"set(\'a\', \'{not a brace}\');"}{"second":1}';
  const found = balancedObjects(text);
  assert.equal(found.length, 2);
  assert.equal(JSON.parse(found[0]).handler, "set('a', '{not a brace}');");

