import { runHandlers, matchingEdges } from "/Users/francip/src/magicapp/app/lib/runtime.ts";

const r = JSON.parse(
  await (await import("node:fs/promises")).readFile(
    "/tmp/magicapp-smoke/response.json",
    "utf8",
  ),
);

const components = r.components.map((c) => ({
  id: c.id,
  type: c.type,
  bounds: { x: c.x, y: c.y, width: c.width, height: c.height },
  props: { label: c.label ?? "", placeholder: c.placeholder ?? "", options: [] },
  dataSource: c.dataSource ?? "",
  stateKey: c.stateKey ?? "",
  confidence: c.confidence ?? 1,
}));

const bindings = r.edges.map((e, i) => ({
  id: `e${i}`,
  source: e.source,
  target: e.target,
  instruction: e.instruction ?? "",
  triggerEvent: e.triggerEvent ?? "click",
  actionType: e.actionType ?? "custom",
  sourceData: e.sourceData ?? "",
  predicate: e.predicate ?? "",
  handler: e.handler,
  tests: e.tests ?? [],
  compiledBy: "omp",
}));

let state = { ...r.initialState };

function click(label) {
  const comp = components.find((c) => c.props.label === label);
  if (!comp) throw new Error(`no component labeled ${label}`);
  const edges = matchingEdges(bindings, comp.id, "click");
  const result = runHandlers(edges, components, state, {
    type: "click",
    value: label,
    componentId: comp.id,
  });
  state = result.state;
  return state.display;
}

const checks = [
  ["7", "7"],
  ["3", "73"],
  ["+", "73"],
  ["4", "4"],
  ["=", "77"],
  ["C", "0"],
  ["5", "5"],
  ["/", "5"],
  ["2", "2"],
  ["=", "2.5"],
  ["C", "0"],
  ["9", "9"],
  ["*", "9"],
  ["9", "9"],
  ["=", "81"],
  ["C", "0"],
  ["8", "8"],
  ["-", "8"],
  ["3", "3"],
  ["=", "5"],
];

let pass = 0;
let fail = 0;
for (const [key, expected] of checks) {
  const got = click(key);
  const ok = got === expected;
  if (ok) pass++;
  else fail++;
  console.log(`${ok ? "ok  " : "FAIL"} press ${key} -> display ${JSON.stringify(got)} (expected ${JSON.stringify(expected)})`);
}

// divide by zero
click("C");
click("5");
click("/");
click("0");
const div0 = click("=");
console.log(`${div0 === "0" ? "ok  " : "FAIL"} 5 / 0 = ${JSON.stringify(div0)} (expected "0")`);

console.log(`\n${pass + (div0 === "0" ? 1 : 0)}/${checks.length + 1} arithmetic checks passed`);

