  const beginStroke = (event: ReactPointerEvent<SVGSVGElement>) => {
    if (mode === "run" || processing || !event.isPrimary) return;
    event.preventDefault();
    // Capture is an optimization, not a requirement: it throws when the pointer
    // is already gone, and losing the stroke over that would be worse.
    try {
      event.currentTarget.setPointerCapture(event.pointerId);
    } catch {
      // Keep drawing without capture.
    }
    const stroke: InkStroke = {
      id: createId("stroke"),
      points: [pointFromEvent(event)],
      processed: false,
    };
    draftRef.current = stroke;
    setDraftStroke(stroke);
  };

  const continueStroke = (event: ReactPointerEvent<SVGSVGElement>) => {
    if (!draftRef.current || mode === "run") return;
    event.preventDefault();
    const native = event.nativeEvent;
    // getCoalescedEvents can legitimately return an empty list; falling through
    // to it would silently drop every point in the stroke.
    const coalesced =
      typeof native.getCoalescedEvents === "function"
        ? native.getCoalescedEvents()
        : [];
    const points = (coalesced.length > 0 ? coalesced : [native]).map(
      pointFromEvent,
    );
    const next = {
      ...draftRef.current,
      points: [...draftRef.current.points, ...points],
    };
    draftRef.current = next;
    setDraftStroke(next);
  };

  const finishStroke = (event: ReactPointerEvent<SVGSVGElement>) => {
    const finished = draftRef.current;
    if (!finished) return;
    event.preventDefault();
    if (event.currentTarget.hasPointerCapture(event.pointerId)) {
      event.currentTarget.releasePointerCapture(event.pointerId);
    }
    draftRef.current = null;
    setDraftStroke(null);

    if (strokeLength(finished) < 12) {
      const tap = finished.points[0];
      const hit = [...graphRef.current.components]
        .reverse()
        .find((component) => hitTest(tap, component, 8));
      if (hit) {
        setSelectedId(hit.id);
        setSidePanel("component");
      } else {
        setSelectedId(null);
        setSidePanel(null);
      }
      return;
    }

    saveHistory();
    setStrokes((current) => [...current, finished]);
  };

  const cancelStroke = () => {
    draftRef.current = null;
    setDraftStroke(null);
  };

  /**
   * Renders the current app plus the unprocessed ink into one PNG. Existing
   * components are drawn as labeled boxes so the model can aim wiring arrows at
   * exact component ids instead of guessing at them.
   */
  const captureCanvasImage = useCallback(async (): Promise<string> => {
    const width = Math.round(canvasSize.width);
…
  }, [canvasSize]);

