const beginStroke = (event: ReactPointerEvent<SVGSVGElement>) => {
  if (mode === "run" || processing || !event.isPrimary) return;
  event.preventDefault();
  // Capture is an optimization, not a requirement: it throws when the pointer
  // is already gone, and losing the stroke over that would be worse.
  try {
    event.currentTarget.setPointerCapture(event.pointerId);
  } catch {
    // Keep drawing without capture.
  }
  const point = pointFromEvent(event);
  // A press that lands on a recognized component starts a drag instead of a
  // stroke: recognized UI is moved, empty canvas is drawn on.
  const hit = [...graphRef.current.components]
    .reverse()
    .find((component) => hitTest(point, component, 0));
  if (hit) {
    dragRef.current = {
      id: hit.id,
      origin: point,
      bounds: { ...hit.bounds },
      moved: false,
    };
    return;
  }
  const stroke: InkStroke = {
    id: createId("stroke"),
    points: [point],
    processed: false,
  };
  draftRef.current = stroke;
  setDraftStroke(stroke);
};

const continueStroke = (event: ReactPointerEvent<SVGSVGElement>) => {
  const drag = dragRef.current;
  if (drag) {
    event.preventDefault();
    const point = pointFromEvent(event);
    const dx = point.x - drag.origin.x;
    const dy = point.y - drag.origin.y;
    // Under the threshold this is still a tap, not a move.
    if (!drag.moved && Math.hypot(dx, dy) < 6) return;
    if (!drag.moved) {
      drag.moved = true;
      saveHistory();
    }
    setGraph((current) => ({
      ...current,
      components: current.components.map((component) =>
        component.id === drag.id
          ? {
              ...component,
              bounds: {
                x: clamp(
                  drag.bounds.x + dx,
                  0,
                  Math.max(0, canvasSize.width - drag.bounds.width),
                ),
                y: clamp(
                  drag.bounds.y + dy,
                  0,
                  Math.max(0, canvasSize.height - drag.bounds.height),
                ),
                width: drag.bounds.width,
                height: drag.bounds.height,
              },
            }
          : component,
      ),
    }));
    return;
  }
  if (!draftRef.current || mode === "run") return;
  event.preventDefault();
  const native = event.nativeEvent;
  // getCoalescedEvents can legitimately return an empty list; falling through
  // to it would silently drop every point in the stroke.
  const coalesced =
    typeof native.getCoalescedEvents === "function"
      ? native.getCoalescedEvents()
      : [];
  const points = (coalesced.length > 0 ? coalesced : [native]).map(
    pointFromEvent,
  );
  const next = {
    ...draftRef.current,
    points: [...draftRef.current.points, ...points],
  };
  draftRef.current = next;
  setDraftStroke(next);
};

const finishStroke = (event: ReactPointerEvent<SVGSVGElement>) => {
  const drag = dragRef.current;
  const finished = draftRef.current;
  if (!drag && !finished) return;
  event.preventDefault();
  if (event.currentTarget.hasPointerCapture(event.pointerId)) {
    event.currentTarget.releasePointerCapture(event.pointerId);
  }
  if (drag) {
    dragRef.current = null;
    // A press-and-release without movement is a tap: select the component.
    if (!drag.moved) {
      setSelectedId(drag.id);
      setSidePanel("component");
    }
    return;
  }
  event.preventDefault();
  if (event.currentTarget.hasPointerCapture(event.pointerId)) {
    event.currentTarget.releasePointerCapture(event.pointerId);
  }
  draftRef.current = null;
  setDraftStroke(null);

  if (strokeLength(finished) < 12) {
    const tap = finished.points[0];
    const hit = [...graphRef.current.components]
      .reverse()
      .find((component) => hitTest(tap, component, 8));
    if (hit) {
      setSelectedId(hit.id);
      setSidePanel("component");
    } else {
      setSelectedId(null);
      setSidePanel(null);
    }
    return;
  }

  saveHistory();
  setStrokes((current) => [...current, finished]);
};

const cancelStroke = () => {
  draftRef.current = null;
  setDraftStroke(null);
  dragRef.current = null;
};

